    @staticmethod
    def _poolscanner():
        # Keep this lazy.  Early import from an external plugin can otherwise
        # race Volatility's Windows symbol-extension import cycle.
        from volatility3.framework.symbols.windows import extensions as _extensions  # noqa: F401
        from volatility3.plugins.windows import poolscanner
        return poolscanner

    @classmethod
    def get_requirements(cls):
        poolscanner = cls._poolscanner()
        return [
            requirements.ModuleRequirement(
                name="kernel",
                description="Windows kernel",
                architectures=["Intel64"],
            ),
            requirements.VersionRequirement(
                name="poolscanner",
                component=poolscanner.PoolScanner,
                version=(3, 0, 0),
            ),
            requirements.BooleanRequirement(
                name="include-freed",
                description=(
                    "Also inspect FREE WfpF pool allocations. Results can be stale/corrupt; "
                    "the validated non-free recovery path does not cover deleted-object recovery."
                ),
                default=False,
                optional=True,
            ),
            requirements.BooleanRequirement(
                name="freed-only",
                description=(
                    "Show only FREE WfpF candidates. Requires --include-freed. "
                    "These rows are research candidates, not validated as current enforcement state."
                ),
                default=False,
                optional=True,
            ),
            requirements.ListRequirement(
                name="filter-id",
                element_type=int,
                description="Filter ID(s) to include",
                optional=True,
            ),
            requirements.ListRequirement(
                name="layer",
                element_type=str,
                description=(
                    "Runtime layer(s) to include. Accepts full FWPS_LAYER_* names, "
                    "short names such as ALE_AUTH_CONNECT_V4, or numeric layer IDs."
                ),
                optional=True,
            ),
            requirements.ListRequirement(
                name="action",
                element_type=str,
                description=(
                    "Action(s) to include. Accepts full FWP_ACTION_* names or short "
                    "names such as BLOCK, PERMIT, CALLOUT_TERMINATING."
                ),
                optional=True,
            ),
            requirements.ListRequirement(
                name="protocol",
                element_type=int,
                description="IP protocol number(s) to include, for example 6 for TCP or 17 for UDP",
                optional=True,
            ),
            requirements.ListRequirement(
                name="port",
                element_type=int,
                description="Local or remote transport port(s) to include",
                optional=True,
            ),
            requirements.BooleanRequirement(
                name="unresolved-only",
                description="Show only filters containing at least one unresolved condition field/value",
                default=False,
                optional=True,
            ),
        ]

    @staticmethod
    def _u16(data, off):
        return struct.unpack_from("<H", data, off)[0]

    @staticmethod
    def _u32(data, off):
        return struct.unpack_from("<I", data, off)[0]

    @staticmethod
    def _u64(data, off):
        return struct.unpack_from("<Q", data, off)[0]

    @staticmethod
    def _i8(value):
        return struct.unpack("<b", bytes([value & 0xFF]))[0]

    @staticmethod
    def _i16(value):
        return struct.unpack("<h", struct.pack("<H", value & 0xFFFF))[0]

    @staticmethod
    def _i32(value):
        return struct.unpack("<i", struct.pack("<I", value & 0xFFFFFFFF))[0]

    @staticmethod
    def _normalize(layer, ptr):
        return int(ptr) & int(layer.address_mask)

    @classmethod
    def _read(cls, layer, ptr, size):
        if not ptr or size <= 0:
            return b""
        try:
            return layer.read(cls._normalize(layer, ptr), size, pad=True)
        except (exceptions.InvalidAddressException, ValueError, TypeError):
            return b""

    @classmethod
    def _pool_state(cls, header):
        try:
            if header.is_free_pool():
                return "FREE"
            if header.is_nonpaged_pool():
                return "NONPAGED"
            if header.is_paged_pool():
                return "PAGED"
        except (AttributeError, exceptions.InvalidAddressException):
            pass
        return "UNKNOWN"

    @classmethod
    def _decode_sid(cls, layer, ptr):
        hdr = cls._read(layer, ptr, 8)
        if len(hdr) < 8:
            return None
        revision = hdr[0]
        subauth_count = hdr[1]
        if revision == 0 or subauth_count > 15:
            return None
        total = 8 + (subauth_count * 4)
        blob = cls._read(layer, ptr, total)
        if len(blob) < total:
            return None
        authority = int.from_bytes(blob[2:8], "big")
        subs = [struct.unpack_from("<I", blob, 8 + (i * 4))[0] for i in range(subauth_count)]
        return "S-{}-{}{}".format(revision, authority, "".join(f"-{x}" for x in subs))

    @classmethod
    def _decode_fwp_value(cls, layer, dtype, raw_union, depth=0):
        rec = {
            "type": int(dtype),
            "type_name": cls.DATA_TYPE_NAMES.get(int(dtype), f"FWP_TYPE_{int(dtype)}"),
            "union_raw": int(raw_union),
            "value": None,
            "resolved": False,
        }

        if depth > 2:
            return rec

        if dtype == 0:  # FWP_EMPTY
            rec["resolved"] = True
        elif dtype == 1:  # FWP_UINT8
            rec["value"] = raw_union & 0xFF
            rec["resolved"] = True
        elif dtype == 2:  # FWP_UINT16
            rec["value"] = raw_union & 0xFFFF
            rec["resolved"] = True
        elif dtype == 3:  # FWP_UINT32
            rec["value"] = raw_union & 0xFFFFFFFF
            rec["resolved"] = True
        elif dtype == 4:  # FWP_UINT64*
            blob = cls._read(layer, raw_union, 8)
            if len(blob) >= 8:
                rec["value"] = struct.unpack_from("<Q", blob, 0)[0]
                rec["resolved"] = True
        elif dtype == 5:  # FWP_INT8
            rec["value"] = cls._i8(raw_union)
            rec["resolved"] = True
        elif dtype == 6:  # FWP_INT16
            rec["value"] = cls._i16(raw_union)
            rec["resolved"] = True
        elif dtype == 7:  # FWP_INT32
            rec["value"] = cls._i32(raw_union)
            rec["resolved"] = True
        elif dtype == 8:  # FWP_INT64*
            blob = cls._read(layer, raw_union, 8)
            if len(blob) >= 8:
                rec["value"] = struct.unpack_from("<q", blob, 0)[0]
                rec["resolved"] = True
        elif dtype == 9:  # FWP_FLOAT inline
            rec["value"] = struct.unpack("<f", struct.pack("<I", raw_union & 0xFFFFFFFF))[0]
            rec["resolved"] = True
        elif dtype == 10:  # FWP_DOUBLE*
            blob = cls._read(layer, raw_union, 8)
            if len(blob) >= 8:
                rec["value"] = struct.unpack_from("<d", blob, 0)[0]
                rec["resolved"] = True
        elif dtype == 11:  # FWP_BYTE_ARRAY16_TYPE*
            blob = cls._read(layer, raw_union, 16)
            if len(blob) == 16:
                rec["value_hex"] = blob.hex()
                rec["resolved"] = True
        elif dtype == 12:  # FWP_BYTE_BLOB_TYPE*
            hdr = cls._read(layer, raw_union, 16)
            if len(hdr) >= 16:
                size = struct.unpack_from("<I", hdr, 0)[0]
                data_ptr = struct.unpack_from("<Q", hdr, 8)[0]
                rec["blob_size"] = size
                if size <= 4096:
                    blob = cls._read(layer, data_ptr, size)
                    if len(blob) == size:
                        rec["value_hex"] = blob.hex()
                        rec["resolved"] = True
        elif dtype == 13:  # FWP_SID
            sid = cls._decode_sid(layer, raw_union)
            if sid:
                rec["value_text"] = sid
                rec["resolved"] = True
        elif dtype == 17:  # FWP_UNICODE_STRING_TYPE
            blob = cls._read(layer, raw_union, 512)
            if blob:
                end = None
                for index in range(0, len(blob) - 1, 2):
                    if blob[index:index + 2] == b"\x00\x00":
                        end = index
                        break
                if end is None:
                    end = len(blob) - (len(blob) % 2)
                rec["value_text"] = blob[:end].decode("utf-16-le", errors="replace")
                rec["resolved"] = True
        elif dtype == 18:  # FWP_BYTE_ARRAY6_TYPE*
            blob = cls._read(layer, raw_union, 6)
            if len(blob) == 6:
                rec["value_hex"] = blob.hex()
                rec["resolved"] = True
        elif dtype == 0x100:  # FWP_V4_ADDR_MASK*
            blob = cls._read(layer, raw_union, 8)
            if len(blob) >= 8:
                addr = struct.unpack_from("<I", blob, 0)[0]
                mask = struct.unpack_from("<I", blob, 4)[0]
                rec["v4_addr"] = addr
                rec["v4_mask"] = mask
                # Preserve integers as canonical evidence; the text form is a convenience.
                rec["v4_addr_text_be"] = str(ipaddress.IPv4Address(addr))
                rec["resolved"] = True
        elif dtype == 0x101:  # FWP_V6_ADDR_MASK*
            blob = cls._read(layer, raw_union, 17)
            if len(blob) >= 17:
                rec["v6_addr_hex"] = blob[:16].hex()
                rec["v6_addr_text"] = str(ipaddress.IPv6Address(blob[:16]))
                rec["v6_prefix_length"] = blob[16]
                rec["resolved"] = True
        elif dtype == 0x102:  # FWP_RANGE_TYPE*
            blob = cls._read(layer, raw_union, 32)
            if len(blob) >= 32:
                low_type = cls._u32(blob, 0x00)
                low_union = cls._u64(blob, 0x08)
                high_type = cls._u32(blob, 0x10)
                high_union = cls._u64(blob, 0x18)
                rec["range_low"] = cls._decode_fwp_value(layer, low_type, low_union, depth + 1)
                rec["range_high"] = cls._decode_fwp_value(layer, high_type, high_union, depth + 1)
                rec["resolved"] = True

        return rec

    @classmethod
    def _decode_conditions(cls, layer, count, cond_ptr):
        if count == 0:
            return [], True
        if count > cls.MAX_CONDITIONS or not cond_ptr:
            return [], False

        total = count * cls.FWPS_CONDITION_SIZE
        blob = cls._read(layer, cond_ptr, total)
        if len(blob) < total:
            return [], False

        conditions = []
        for index in range(count):
            off = index * cls.FWPS_CONDITION_SIZE
            field_id = cls._u16(blob, off + 0x00)
            reserved = cls._u16(blob, off + 0x02)
            match_type = cls._u32(blob, off + 0x04)
            dtype = cls._u32(blob, off + 0x08)
            raw_union = cls._u64(blob, off + 0x10)
            conditions.append(
                {
                    "index": index,
                    "field_id": field_id,
                    "reserved": reserved,
                    "match_type": match_type,
                    "match_name": cls.MATCH_NAMES.get(match_type, f"FWP_MATCH_{match_type}"),
                    "value": cls._decode_fwp_value(layer, dtype, raw_union),
                }
            )
        return conditions, True

    @classmethod
    def _layer_name(cls, layer_id):
        if 0 <= int(layer_id) < len(cls.BUILTIN_LAYER_NAMES):
            return cls.BUILTIN_LAYER_NAMES[int(layer_id)]
        return f"FWPS_LAYER_ID_{int(layer_id)}"

    @classmethod
    def _enrich_conditions(cls, layer_id, conditions):
        names = cls.FIELD_NAMES_BY_LAYER.get(int(layer_id))
        enriched = []
        for condition in conditions:
            item = dict(condition)
            field_id = int(item.get("field_id", -1))
            field_name = None
            if names is not None and 0 <= field_id < len(names):
                field_name = names[field_id]
            item["field_name"] = field_name
            item["field_name_resolved"] = field_name is not None
            enriched.append(item)
        return enriched

    @classmethod
    def _value_summary(cls, value):
        if value.get("value") is not None:
            return str(value["value"])
        for key in ("value_text", "value_hex", "v4_addr_text_be", "v6_addr_text"):
            if key in value:
                return str(value[key])
        if "range_low" in value and "range_high" in value:
            return f"[{cls._value_summary(value['range_low'])}..{cls._value_summary(value['range_high'])}]"
        return f"ptr=0x{int(value.get('union_raw', 0)):x}"

    @classmethod
    def _conditions_summary(cls, conditions):
        parts = []
        for cond in conditions:
            value = cond.get("value", {})
            parts.append(
                "{field} {match} {dtype}={value}".format(
                    field=cond.get("field_name") or f"field#{cond.get('field_id')}",
                    match=cond.get("match_name"),
                    dtype=value.get("type_name"),
                    value=cls._value_summary(value),
                )
            )
        return "; ".join(parts)

    @classmethod
    def _weight_summary(cls, weight):
        if weight.get("type") == 0:
            return "AUTO"
        return f"{weight.get('type_name')}={cls._value_summary(weight)}"

    @classmethod
    def _is_structurally_valid(cls, filter_id, weight_type, num_conditions, action_type, conditions_readable):
        if filter_id <= 0:
            return False
        if weight_type not in cls.VALID_WEIGHT_TYPES:
            return False
        if num_conditions > cls.MAX_CONDITIONS:
            return False
        if action_type not in cls.ACTION_NAMES:
            return False
        if num_conditions and not conditions_readable:
            return False
        return True

    def _generator(self):
        poolscanner = self._poolscanner()
        kernel = self.context.modules[self.config["kernel"]]
        layer = self.context.layers[kernel.layer_name]
        symtab = kernel.symbol_table_name
        alignment = 0x10
        include_freed = bool(self.config.get("include-freed", False))

        try:
            header_size = int(kernel.get_type("_POOL_HEADER").size)
        except Exception:
            header_size = 0x10

        page_type = poolscanner.PoolType.PAGED | poolscanner.PoolType.NONPAGED
        if include_freed:
            page_type |= poolscanner.PoolType.FREE

        constraint = poolscanner.PoolConstraint(
            b"WfpF",
            type_name=symtab + constants.BANG + "_POOL_HEADER",
            page_type=page_type,
            size=(self.WFPF_ALLOCATION_SIZE, self.WFPF_ALLOCATION_SIZE),
            skip_type_test=True,
        )

        seen_active_ids = set()
        for _constraint, header in poolscanner.PoolScanner.pool_scan(
            self.context,
            self.config["kernel"],
            kernel.layer_name,
            symtab,
            [constraint],
            alignment=alignment,
        ):
            try:
                if int(header.BlockSize) * alignment != self.WFPF_ALLOCATION_SIZE:
                    continue

                pool_state = self._pool_state(header)
                data_offset = int(header.vol.offset) + header_size
                shell = layer.read(data_offset, 0x70, pad=True)
                if len(shell) < 0x38:
                    continue

                runtime_ptr_raw = self._u64(shell, self.WFPF_RUNTIME_PTR_OFFSET)
                if not runtime_ptr_raw:
                    continue
                runtime_ptr = self._normalize(layer, runtime_ptr_raw)
                layer_id = self._u32(shell, self.WFPF_LAYER_ID_OFFSET)

                runtime = self._read(layer, runtime_ptr_raw, self.FWPS_FILTER_SIZE)
                if len(runtime) < self.FWPS_FILTER_SIZE:
                    continue

                # Documented x64 FWPS_FILTER2/FWPS_FILTER3-compatible layout.
                filter_id = self._u64(runtime, 0x00)
                weight_type = self._u32(runtime, 0x08)
                weight_union = self._u64(runtime, 0x10)
                weight = self._decode_fwp_value(layer, weight_type, weight_union)
                sublayer_weight = self._u16(runtime, 0x18)
                flags = self._u16(runtime, 0x1A)
                num_conditions = self._u32(runtime, 0x1C)
                condition_ptr_raw = self._u64(runtime, 0x20)
                condition_ptr = self._normalize(layer, condition_ptr_raw) if condition_ptr_raw else 0
                action_type = self._u32(runtime, 0x28)
                callout_id = self._u32(runtime, 0x2C)
                context = self._u64(runtime, 0x30)
                provider_context_raw = self._u64(runtime, 0x38)
                provider_context = self._normalize(layer, provider_context_raw) if provider_context_raw else 0

                conditions, conditions_readable = self._decode_conditions(
                    layer, num_conditions, condition_ptr_raw
                )
                conditions = self._enrich_conditions(layer_id, conditions)

                if not self._is_structurally_valid(
                    filter_id, weight_type, num_conditions, action_type, conditions_readable
                ):
                    continue

                # Default non-free output is one row per runtime filter ID. FREE mode
                # intentionally permits additional stale candidates for research.
                if not include_freed:
                    if filter_id in seen_active_ids:
                        continue
                    seen_active_ids.add(filter_id)

                yield (
                    0,
                    (
                        "WfpF",
                        pool_state,
                        format_hints.Hex(int(header.vol.offset)),
                        format_hints.Hex(data_offset),
                        format_hints.Hex(runtime_ptr),
                        filter_id,
                        layer_id,
                        self._layer_name(layer_id),
                        self.ACTION_NAMES.get(action_type, f"FWP_ACTION_0x{action_type:x}"),
                        action_type,
                        self._weight_summary(weight),
                        weight_type,
                        json.dumps(weight, sort_keys=True, separators=(",", ":")),
                        sublayer_weight,
                        flags,
                        num_conditions,
                        format_hints.Hex(condition_ptr),
                        conditions_readable,
                        self._conditions_summary(conditions),
                        json.dumps(conditions, sort_keys=True, separators=(",", ":")),
                        callout_id,
                        context,
                        format_hints.Hex(provider_context),
                    ),
                )
            except (exceptions.InvalidAddressException, ValueError, TypeError, struct.error):
                continue

    @classmethod
    def _blob_text(cls, value):
        """Best-effort display of byte blobs without changing decoded evidence."""
        raw = value.get("value_hex")
        if not raw:
            return None
        try:
            blob = bytes.fromhex(raw)
        except (TypeError, ValueError):
            return None
        if not blob:
            return ""
        # App/image IDs are commonly UTF-16LE device/path strings.  Decode only
        # when the result is printable enough to be useful; raw hex remains in
        # ConditionsJson regardless.
        if len(blob) >= 4 and len(blob) % 2 == 0:
            try:
                text = blob.decode("utf-16-le", errors="strict").rstrip("\x00")
                if text and sum(ch.isprintable() for ch in text) / len(text) >= 0.85:
                    return text
            except (UnicodeDecodeError, ZeroDivisionError):
                pass
        return None

    @classmethod
    def _address_text(cls, value):
        dtype = int(value.get("type", -1))
        if dtype == 3 and value.get("value") is not None:  # FWP_UINT32 IPv4, host order
            try:
                raw = int(value["value"]) & 0xFFFFFFFF
                return str(ipaddress.IPv4Address(struct.pack("<I", raw)))
            except (ValueError, TypeError, struct.error):
                return None
        if dtype == 0x100 and value.get("v4_addr") is not None:
            try:
                addr = str(ipaddress.IPv4Address(struct.pack("<I", int(value["v4_addr"]) & 0xFFFFFFFF)))
                mask = str(ipaddress.IPv4Address(struct.pack("<I", int(value.get("v4_mask", 0)) & 0xFFFFFFFF)))
                return f"{addr}/{mask}"
            except (ValueError, TypeError, struct.error):
                return None
        if dtype == 11 and value.get("value_hex"):
            try:
                blob = bytes.fromhex(value["value_hex"])
                if len(blob) == 16:
                    return str(ipaddress.IPv6Address(blob))
            except (ValueError, TypeError):
                return None
        if dtype == 0x101 and value.get("v6_addr_text"):
            prefix = value.get("v6_prefix_length")
            return (
                f"{value['v6_addr_text']}/{prefix}"
                if prefix is not None
                else str(value["v6_addr_text"])
            )
        return None

    @classmethod
    def _display_condition_value(cls, field_name, value):
        if not isinstance(value, dict):
            return ""
        if field_name and (
            field_name.endswith("_IP_LOCAL_ADDRESS")
            or field_name.endswith("_IP_REMOTE_ADDRESS")
            or field_name.endswith("_IP_SOURCE_ADDRESS")
            or field_name.endswith("_IP_DESTINATION_ADDRESS")
            or field_name.endswith("_IP_LOCAL_ADDRESS_V4")
            or field_name.endswith("_IP_REMOTE_ADDRESS_V4")
            or field_name.endswith("_IP_LOCAL_ADDRESS_V6")
            or field_name.endswith("_IP_REMOTE_ADDRESS_V6")
        ):
            address = cls._address_text(value)
            if address is not None:
                return address

        if field_name and (
            "APP_ID" in field_name
            or field_name.endswith("_IMAGE_NAME")
            or field_name.endswith("_PIPE")
            or field_name.endswith("_RPC_SERVER_NAME")
        ):
            text = cls._blob_text(value)
            if text is not None:
                return text

        return cls._value_summary(value)

    @classmethod
    def _condition_projection(cls, conditions):
        projected = {
            "protocol_number": None,
            "protocol": "",
            "local_address": "",
            "local_port": None,
            "remote_address": "",
            "remote_port": None,
            "app_id": "",
            "user_id": "",
            "package_id": "",
            "direction": "",
            "resolved_count": 0,
            "total_count": len(conditions),
            "unresolved_count": 0,
        }

        for condition in conditions:
            field = condition.get("field_name") or ""
            value = condition.get("value") or {}
            field_resolved = bool(condition.get("field_name_resolved", False))
            value_resolved = bool(value.get("resolved", False))
            if field_resolved and value_resolved:
                projected["resolved_count"] += 1
            else:
                projected["unresolved_count"] += 1

            display = cls._display_condition_value(field, value)

            if field.endswith("_IP_PROTOCOL") or field.endswith("_EMBEDDED_PROTOCOL"):
                number = value.get("value")
                if isinstance(number, int):
                    projected["protocol_number"] = number
                    name = cls.IP_PROTOCOL_NAMES.get(number)
                    projected["protocol"] = f"{name}/{number}" if name else str(number)
            elif field.endswith("_IP_LOCAL_ADDRESS") or field.endswith("_IP_LOCAL_ADDRESS_V4") or field.endswith("_IP_LOCAL_ADDRESS_V6"):
                projected["local_address"] = display
            elif field.endswith("_IP_REMOTE_ADDRESS") or field.endswith("_IP_REMOTE_ADDRESS_V4") or field.endswith("_IP_REMOTE_ADDRESS_V6"):
                projected["remote_address"] = display
            elif field.endswith("_IP_LOCAL_PORT") or field.endswith("_EMBEDDED_LOCAL_PORT"):
                number = value.get("value")
                if isinstance(number, int):
                    projected["local_port"] = number
            elif field.endswith("_IP_REMOTE_PORT") or field.endswith("_EMBEDDED_REMOTE_PORT"):
                number = value.get("value")
                if isinstance(number, int):
                    projected["remote_port"] = number
            elif field.endswith("_ALE_APP_ID") and not projected["app_id"]:
                projected["app_id"] = display
            elif field.endswith("_ALE_USER_ID") and not projected["user_id"]:
                projected["user_id"] = display
            elif field.endswith("_ALE_PACKAGE_ID") and not projected["package_id"]:
                projected["package_id"] = display
            elif field.endswith("_DIRECTION") and not projected["direction"]:
                projected["direction"] = display

        return projected

    @classmethod
    def _short_action(cls, action):
        prefix = "FWP_ACTION_"
        return action[len(prefix):] if action.startswith(prefix) else action

    @classmethod
    def _recovery_label(cls, pool_state):
        if pool_state == "FREE":
            return "FREE_CANDIDATE"
        if pool_state in ("NONPAGED", "PAGED"):
            return "ALLOCATED_WFPF_RECORD"
        return "UNKNOWN"

    @staticmethod
    def _config_list(config, name):
        value = config.get(name, None)
        if value is None:
            return []
        return [x for x in value if x is not None]

    @classmethod
    def _match_layer_selector(cls, layer_id, layer_name, selector):
        text = str(selector).strip()
        if not text:
            return True
        if text.isdigit():
            return int(text) == int(layer_id)
        normalized = text.upper()
        if not normalized.startswith("FWPS_LAYER_"):
            normalized = "FWPS_LAYER_" + normalized
        return normalized == str(layer_name).upper()

    @classmethod
    def _match_action_selector(cls, action, selector):
        normalized = str(selector).strip().upper()
        if not normalized:
            return True
        if not normalized.startswith("FWP_ACTION_"):
            normalized = "FWP_ACTION_" + normalized
        return normalized == str(action).upper()

    def _row_selected(self, raw, projection):
        filter_ids = [int(x) for x in self._config_list(self.config, "filter-id")]
        if filter_ids and int(raw[5]) not in filter_ids:
            return False

        layers = self._config_list(self.config, "layer")
        if layers and not any(self._match_layer_selector(raw[6], raw[7], x) for x in layers):
            return False

        actions = self._config_list(self.config, "action")
        if actions and not any(self._match_action_selector(raw[8], x) for x in actions):
            return False

        protocols = [int(x) for x in self._config_list(self.config, "protocol")]
        if protocols and projection["protocol_number"] not in protocols:
            return False

        ports = [int(x) for x in self._config_list(self.config, "port")]
        if ports and projection["local_port"] not in ports and projection["remote_port"] not in ports:
            return False

        if bool(self.config.get("unresolved-only", False)) and projection["unresolved_count"] == 0:
            return False

        if bool(self.config.get("freed-only", False)):
            if not bool(self.config.get("include-freed", False)):
                return False
            if raw[1] != "FREE":
                return False

        return True

    def _investigator_generator(self):
        for depth, raw in self._generator():
            try:
                conditions = json.loads(raw[19])
            except (TypeError, ValueError, json.JSONDecodeError):
                conditions = []

            projection = self._condition_projection(conditions)
            if not self._row_selected(raw, projection):
                continue

            resolution = f"{projection['resolved_count']}/{projection['total_count']}"
            yield (
                depth,
                (
                    raw[5],  # FilterId
                    self._short_action(raw[8]),
                    raw[7],  # LayerName
                    projection["protocol"],
                    projection["local_address"],
                    projection["local_port"] if projection["local_port"] is not None else 0,
                    projection["remote_address"],
                    projection["remote_port"] if projection["remote_port"] is not None else 0,
                    projection["app_id"],
                    projection["user_id"],
                    projection["package_id"],
                    projection["direction"],
                    resolution,
                    raw[18],  # Conditions
                    self._recovery_label(raw[1]),
                    raw[1],  # PoolState
                    raw[20], # CalloutId
                    raw[6],  # LayerId
                    raw[8],  # Action full
                    raw[9],  # ActionType
                    raw[10], # Weight
                    raw[11], # WeightType
                    raw[12], # WeightJson
                    raw[13], # SubLayerWeight
                    raw[14], # Flags
                    raw[15], # NumFilterConditions
                    raw[16], # FilterCondition
                    raw[17], # ConditionsReadable
                    raw[19], # ConditionsJson
                    raw[21], # Context
                    raw[22], # ProviderContext
                    raw[2],  # WfpFHeader
                    raw[3],  # WfpFData
                    raw[4],  # RuntimeFilter
                    raw[0],  # Tag
                ),
            )

    def run(self):
        return renderers.TreeGrid(
            [
                ("FilterId", int),
                ("Disposition", str),
                ("LayerName", str),
                ("Protocol", str),
                ("LocalAddress", str),
                ("LocalPort", int),
                ("RemoteAddress", str),
                ("RemotePort", int),
                ("AppId", str),
                ("UserId", str),
                ("PackageId", str),
                ("Direction", str),
                ("ConditionResolution", str),
                ("Conditions", str),
                ("Recovery", str),
                ("PoolState", str),
                ("CalloutId", int),
                ("LayerId", int),
                ("Action", str),
                ("ActionType", int),
                ("Weight", str),
                ("WeightType", int),
                ("WeightJson", str),
                ("SubLayerWeight", int),
                ("Flags", int),
                ("NumFilterConditions", int),
                ("FilterCondition", format_hints.Hex),
                ("ConditionsReadable", bool),
                ("ConditionsJson", str),
                ("Context", int),
                ("ProviderContext", format_hints.Hex),
                ("WfpFHeader", format_hints.Hex),
                ("WfpFData", format_hints.Hex),
                ("RuntimeFilter", format_hints.Hex),
                ("Tag", str),
            ],
            self._investigator_generator(),
        )
